r_{n+1} - r_n &= w_{n+1} - w_n - \frac{1}{w_{n+1}} + \frac{1}{w_n} + O\left(\frac{1}{w_n^3}\right)\\
&= \pi + \frac{1}{w_n} - \frac{1}{w_n + \pi} + O\left(\frac{1}{w_n^3}\right)\\
&= \pi + \frac{\pi}{w_n(w_n + \pi)} + O\left(\frac{1}{w_n^3}\right)
\end{align}

